-- =====================================================================
-- 매칭 평가용 가상 공고 150건 (AI-B 작성 · 원본 ai/data/eval/jobs_general.json)
-- 실행: mysql -u <계정> -p ieum < ai/data/eval/eval_jobs.sql   (schema.sql · seed.sql 실행 뒤)
-- - id 900001~900150 고정, source 'EVAL', external_id 'eval-<id>' (seed 의 'dev-501' 방식)
-- - 다시 실행해도 중복되지 않는다: BE 배치 upsert 처럼 ON DUPLICATE KEY UPDATE 로 같은 id 를 덮어쓴다
-- - content_hash = SHA-256(description) (BE SeoulJobParser 와 같은 계산)
-- - job_code = application.yml it-job-codes 의 코드. IT 코드 목록에 없는 직종 14건은 NULL
--   (IT 기술영업원(전산장비,소프트웨어) · 감시카메라 및 보안장치 설치·수리원 · 기타 경호 및 보안 관련 종사원 · 보안 관제원 · 여행 상품 개발자 · 통계·데이터 관련 사무원)
-- - is_active = 마감일이 2026-10-29 이후면 1. BE 배치는 source 'SEOUL_API' 만 끄므로 이 공고는 켜진 채 남는다
-- - raw 는 API 원본이 없어 NULL
-- 빼기: DELETE FROM job_posting WHERE source = 'EVAL';
-- 주의: id 를 직접 넣으므로 job_posting AUTO_INCREMENT 가 900151 으로 올라간다 (이후 배치 공고 id 도 그 뒤부터)
-- 모든 회사 · 주소 · 본문은 가상 데이터, 연락처는 [연락처 생략].
-- =====================================================================
USE ieum;
SET NAMES utf8mb4;

AS new
ON DUPLICATE KEY UPDATE
  company_name = new.company_name,
  title = new.title,
  job_code = new.job_code,
  job_category = new.job_category,
  location = new.location,
  work_address = new.work_address,
  employment_type = new.employment_type,
  career = new.career,
  education = new.education,
  salary_text = new.salary_text,
  description = new.description,
  deadline_on = new.deadline_on,
  until_filled = new.until_filled,
  posted_on = new.posted_on,
  is_active = new.is_active,
  content_hash = new.content_hash,
  synced_at = NOW();
